// Block 8: resolve the managed|bare lane flag, fail-safe to bare. Preserves the full Stage A
// context (spread from Call Assemble Context) so the bare lane's Call Execute LLM mapping ($json.prompt etc.)
// still resolves downstream. On a DB error (onError=continueRegularOutput passes the input item through) or
// a missing/malformed flag, agent_lane is absent -> lane_unreadable=true -> bare + a WARN (Lane Unreadable?).
const ctx = $('Call Assemble Context').first().json || {};
const row = ($input.first() && $input.first().json) || {};
let lane = String(row.agent_lane || '').trim().toLowerCase();
let lane_unreadable = false;
if (lane !== 'managed' && lane !== 'bare') { lane_unreadable = true; lane = 'bare'; }
// ADR-060: capture a lower-bound timestamp BEFORE the session runs so the managed footer can sum
// only THIS execution's image-gen cost rows (triggered_by='image_mcp', clickup_task_id, created_at>=since_ts).
// 5s buffer absorbs any n8n<->DB clock skew; prior runs' image rows are minutes+ older so the window excludes them.
const since_ts = new Date(Date.now() - 5000).toISOString();
return [{ json: Object.assign({}, ctx, { agent_lane: lane, lane_unreadable: lane_unreadable, since_ts: since_ts }) }];

