parameters.jsCode:
const ctx = $('Call Assemble Context').first().json || {};
let blocks = [];
try { blocks = JSON.parse(ctx.image_blocks_json || '[]'); } catch (e) { blocks = []; }
const file_map = [];
for (const b of (Array.isArray(blocks) ? blocks : [])) {
  const source_ref = String((b && b.source_ref) || '').trim();
  const url = String((b && b.ref) || '').trim();
  if (!source_ref || !url) continue;
  file_map.push({ file_id: 'att_' + source_ref, url, mime: String((b && b.mime) || 'image/*'), source_ref });
}
return [{ json: { file_map } }];

parameters.query:
insert into public.agent_input_file_map (file_id, url, mime, source_ref)
select file_id, url, mime, source_ref
from jsonb_to_recordset($1::jsonb) as x(file_id text, url text, mime text, source_ref text)
where file_id is not null
on conflict (file_id) do update set url = excluded.url, mime = excluded.mime, source_ref = excluded.source_ref;
